; DMAIN.S - DASH CORE ENTRY & EVENT LOOP

; PRIVATE ZERO-PAGE REGISTERS DOCUMENTED IN AGENTS.MD. THESE MUST BE
; DECLARED BEFORE THEIR FIRST USE SO BOTH CASM AND CA65 SELECT ZERO-PAGE
; ADDRESSING. TWO-BYTE PAIRS USE THE BASE CONSTANT PLUS 1 FOR THE HIGH BYTE.
DISPATCHVECTOR = $70
CURRENTROW = $72
SCREENDESTPTR = $73
STRINGSRCPTR = $75
CURRENTCOL = $77
FMTWORK = $78
DIV10REM = $7A
COLORPTR = $7B
CHARSTASH = $7D
MAXLEN = $7E
SRCIDX = $7F

; DASH-MOD WP3: NAMED CONSTANTS. DECLARED HERE, BEFORE ALL CODE, SO BOTH
; CASM AND CA65 RESOLVE THEM WITHOUT A FORWARD REFERENCE. STRUCTURAL
; INVARIANTS OVER THESE (PAGECOUNT == 3, ZP MAP CONTIGUOUS, API CODES IN
; THE $40-$5F BAND) ARE .ASSERT-GUARDED IN DASH_WRAPPER.S -- CA65-ONLY,
; SINCE CASM'S EXPRESSION GRAMMAR HAS NO COMPARISON OPERATOR. THE
; CA65<->CASM BYTE CROSS-CHECK COVERS THE CASM SIDE.

; --- PAGE MODEL ---
PAGE_SYS = 0
PAGE_APP = 1
PAGE_VMM = 2
PAGECOUNT = 3
PAGE_ROUTINE_ENTRY_SIZE = 2   ; PAGEROUTINETABLE STRIDE (ONE .WORD); DISPATCHPAGE'S ASL A

; --- KEYBOARD INPUT (DMAIN.S EVENT LOOP) ---
KERNAL_GETIN = $FFE4
KEY_F1 = $85                  ; F1/F3/F5 = $85/$86/$87 -> PAGE 0/1/2 BY SUBTRACTION
KEY_CASE_MASK = $DF           ; AND-MASK CLEARING BIT 5: FOLDS THE SHIFTED/
                             ; LOWERCASE-CHARSET LETTER VARIANT ONTO ITS BASE CODE
KEY_T = $54                   ; RUN VMM TEST (VMM PAGE ONLY)
KEY_R = $52                   ; FORCE REDRAW
KEY_Q = $51                   ; EXIT

; --- SCREEN GEOMETRY ---
SCREEN_COLS = 40
SCREEN_ROWS = 25
SCREEN_RAM = $0400
COLOR_RAM = $D800
COLORRAM_DELTA_HI = $D4       ; COLOR RAM HIGH BYTE - SCREEN RAM HIGH BYTE

; --- SCREEN CODES / COLORS ---
SCREENCODE_SPACE = $20
SCREENCODE_VBAR = $5D         ; VERTICAL FRAME LINE
TEXT_COLOR = $0E              ; DEFAULT TEXT COLOR (LIGHT BLUE)
ACTIVE_TAB_COLOR = $01        ; ACTIVE TAB LABEL COLOR (WHITE)

; --- FORMATTING (DFMT.S) ---
DEC_RADIX = 10
PETSCII_SYMBOL_BASE = $40     ; PETSCII $40-$5F REBASE TO SCREEN CODES BY -$40
PETSCII_LOWER_BASE = $60      ; PETSCII >= $60 PASSES THROUGH UNCHANGED
SCREENCODE_DOT = $2E          ; '.' -- VERSION-NUMBER SEPARATOR
COL_CONTENT = 2               ; DEFAULT LEFT CONTENT MARGIN COLUMN

; --- SYSTEM PAGE (DSYS.S): CONTENT ROW INDICES ---
ROW_SYS_TITLE = 4
ROW_SYS_VERSION = 6
ROW_SYS_DEVICE = 7
ROW_SYS_VIDEO = 8
ROW_SYS_RANGE = 9
ROW_SYS_PROTECTED = 10
ROW_SYS_VMM = 11
ROW_SYS_PGSIZE = 12
ROW_SYS_PGTOTAL = 13
ROW_SYS_USEDFREE = 14
ROW_SYS_APPS = 15

; --- DOS_GET_SYSTEM_INFO ($5C) RECORD: SIZE, VERSION, FIELD OFFSETS.
;     MIRRORS SYS_INFO_OFF_* IN INCLUDE/COMMAND64.INC (WHICH CASM CANNOT
;     .INCLUDE -- NO EQUATE IMPORT IN THE DUAL-ASSEMBLER SUBSET).
SYS_STRUCT_VERSION = 2
SYS_STRUCT_SIZE = 24
SYS_OFF_STRUCTVERSION = 0
SYS_OFF_STRUCTSIZE = 1
SYS_OFF_OSMAJOR = 2
SYS_OFF_OSMINOR = 3
SYS_OFF_OSSTAGE = 4
SYS_OFF_CURRENTDEVICE = 5
SYS_OFF_VIDEOSTANDARD = 6
SYS_OFF_USERPROGSTART = 7     ; LO; +1 = HI
SYS_OFF_USERPROGEND = 9      ; LO; +1 = HI
SYS_OFF_VMMFLAGS = 11
SYS_OFF_VMMPAGESIZE = 12     ; LO; +1 = HI
SYS_OFF_VMMTOTALPAGES = 14   ; LO; +1 = HI
SYS_OFF_VMMALLOCPAGES = 16   ; LO; +1 = HI
SYS_OFF_VMMFREEPAGES = 18    ; LO; +1 = HI
SYS_OFF_APPMAXSLOTS = 20
SYS_OFF_APPUSEDSLOTS = 21
SYS_OFF_OSPATCH = 22
SYS_VMMFLAG_ACTIVE = 1        ; BIT 0
SYS_VMMFLAG_REU_PROBED = 2    ; BIT 1
VIDEO_NTSC = 0
VIDEO_PAL = 1
SCREENCODE_DASH = $2D         ; '-'

; --- APPLICATIONS PAGE (DAPP.S) ---
ROW_APP_HEADER = 4
ROW_APP_SLOT0 = 5            ; SLOT N RENDERS ON ROW (ROW_APP_SLOT0 + N)
COL_APP_RANGE = 18
COL_APP_SIZE = 28
COL_APP_FLAGS = 33
APP_NAME_WIDTH = 15

; --- DOS_GET_APP_INFO ($5D) RECORD ---
APP_STRUCT_VERSION = 1
APP_STRUCT_SIZE = 24
APP_MAX_SLOTS = 16
APP_OFF_STRUCTVERSION = 0
APP_OFF_STRUCTSIZE = 1
APP_OFF_FLAGS = 3
APP_OFF_LOADADDR = 4        ; LO; +1 = HI
APP_OFF_SIZE = 6            ; LO; +1 = HI
APP_OFF_NAMELEN = 8
APP_OFF_NAMEDATA = 9
APP_FLAG_USED = 1            ; BIT 0
APP_FLAG_RUNNING = 2         ; BIT 1
APP_FLAG_REU = 4             ; BIT 2
APP_FLAG_STACK = 8           ; BIT 3
DOS_ERR_SLOT_EMPTY = $02

; --- VMM TEST PAGE (DVMM.S) ---
ROW_VMM_TITLE = 4
ROW_VMM_STATUS = 6
ROW_VMM_ALLOC = 8
ROW_VMM_PATTERN = 9
ROW_VMM_STAGE = 10
ROW_VMM_OFFSET = 11
ROW_VMM_EXPECT = 12
ROW_VMM_INSTR = 14
VMM_BLOCK_COUNT = 16
VMM_PATTERN_COUNT = 3
VMM_ALLOC_PARAGRAPHS = $0100  ; 256 PARAGRAPHS OF 16 BYTES = ONE 4KB PAGE
VMM_BLOCK_SIZE = $0100        ; ONE 256-BYTE TRANSFER BLOCK / VMMBUFFER SIZE
VMMSTATE_UNAVAIL = 0
VMMSTATE_READY = 1
VMMSTATE_RUNNING = 2
VMMSTATE_PASSED = 3
VMMSTATE_FAILED = 4
VMMSTATE_CLEANUPFAIL = 5
VMMFAIL_ALLOC = 0
VMMFAIL_WRITE = 1
VMMFAIL_READ = 2
VMMFAIL_COMPARE = 3
VMMFAIL_FREE = 4
VMMFAIL_INTERNAL = 5

; --- DOS SERVICE-BUS CALL CODES (A = CODE, JSR OS_API) ---
OS_API = $1000
DOS_ALLOC_MEM = $48
DOS_FREE_MEM = $49
DOS_EXIT = $4C
DOS_VMM_READ = $59
DOS_VMM_WRITE = $5A
DOS_GET_SYSTEM_INFO = $5C
DOS_GET_APP_INFO = $5D

START:
    CLD                     ; CLEAR DECIMAL MODE

    ; SET INITIAL PAGE TO SYSTEM, FORCE THE FIRST REDRAW
    LDA #PAGE_SYS
    STA CURRPAGE
    JSR MARKREDRAW
    ; FALL INTO EVENTLOOP

EVENTLOOP:
    LDA NEEDREDRAW
    BEQ POLLINPUT

    LDA #0                  ; CLEAR NEEDREDRAW BEFORE DISPATCH SO A PAGE
    STA NEEDREDRAW          ; RENDERER CAN RE-REQUEST ITS OWN REDRAW
    JSR DISPATCHPAGE        ; PAGE DISPATCH TRAMPOLINE

POLLINPUT:
    JSR KERNAL_GETIN
    TAX                     ; KEY CODE IN X
    BEQ EVENTLOOP           ; NO KEY PRESSED

    ; --- F1/F3/F5: SELECT PAGE 0/1/2. THE FUNCTION KEYS ARE CONSECUTIVE
    ;     ($85/$86/$87) AND MAP 1:1 ONTO THE PAGE INDICES, SO THE PAGE IS
    ;     (KEY - KEY_F1) RATHER THAN THREE SEPARATE COMPARES.
    CPX #KEY_F1
    BCC @NOTPAGEKEY
    CPX #(KEY_F1 + PAGECOUNT)
    BCS @NOTPAGEKEY
    TXA
    SEC
    SBC #KEY_F1            ; A = PAGE INDEX (0..PAGECOUNT-1)
    STA CURRPAGE
    JSR MARKREDRAW
    JMP EVENTLOOP

@NOTPAGEKEY:
    ; --- T/R/Q: EACH HAS TWO PETSCII CODES (THE UNSHIFTED FORM AND THE
    ;     SHIFTED/LOWERCASE-CHARSET FORM, DIFFERING ONLY IN BIT 5). FOLD
    ;     WITH KEY_CASE_MASK SO ONE COMPARE MATCHES BOTH. EVERY OTHER KEY
    ;     FOLDS TO SOMETHING THAT MATCHES NONE OF T/R/Q AND IS IGNORED.
    TXA
    AND #KEY_CASE_MASK
    TAX
    CPX #KEY_T
    BEQ TRYRUNVMMTEST
    CPX #KEY_R
    BEQ SETREDRAW
    CPX #KEY_Q
    BEQ EXITAPP
    JMP EVENTLOOP           ; IGNORE EVERY OTHER KEY

; MARKREDRAW - REQUEST A FULL PAGE REDRAW ON THE NEXT EVENTLOOP PASS.
; INPUT: NONE. OUTPUT: NEEDREDRAW = 1. CLOBBERS: A.
MARKREDRAW:
    LDA #1
    STA NEEDREDRAW
    RTS

; TRYRUNVMMTEST - 'T' RUNS THE VMM TEST, BUT ONLY ON THE VMM TEST PAGE;
; PRESSED ON ANY OTHER PAGE IT IS SILENTLY IGNORED.
TRYRUNVMMTEST:
    LDA CURRPAGE
    CMP #PAGE_VMM
    BNE @IGNORE
    JSR DVMMRUNTEST
    JSR MARKREDRAW
@IGNORE:
    JMP EVENTLOOP

SETREDRAW:
    JSR MARKREDRAW
    JMP EVENTLOOP

EXITAPP:
    LDA #DOS_EXIT
    JSR OS_API              ; CALL OS SERVICE BUS
    RTS                     ; SAFE FALLBACK

DISPATCHPAGE:
    ; 1. VALIDATE CURRPAGE (0..PAGECOUNT-1). RESET TO SYSTEM IF OUT OF RANGE.
    LDA CURRPAGE
    CMP #PAGECOUNT
    BCC @PAGEVALID
    LDA #PAGE_SYS
    STA CURRPAGE
@PAGEVALID:
    ; 2. SETUP TRAMPOLINE CALL
    LDA CURRPAGE
    ASL A                     ; INDEX *= PAGE_ROUTINE_ENTRY_SIZE (2)
    TAY
    
    LDA PAGEROUTINETABLE, Y
    STA DISPATCHVECTOR
    INY
    LDA PAGEROUTINETABLE, Y
    STA DISPATCHVECTOR+1

    ; 3. PUSH RETURN ADDRESS - 1 (@RETURN - 1) ON STACK
    LDA #>@RETURNMINUSONE
    PHA
    LDA #<@RETURNMINUSONE
    PHA

    ; 4. JMP INDIRECT THROUGH ZP DISPATCHVECTOR
    JMP (DISPATCHVECTOR)

@RETURNMINUSONE:
    .BYTE 0                 ; ONE-BYTE FILLER SO RTS LANDS ON @RETURN
@RETURN:
    RTS

; DASH IS BUILT FROM A SINGLE ENTRY FILE: THIS FILE PULLS IN THE OTHER SIX
; SOURCES VIA .INCLUDE, IN THE SAME ORDER THE PRE-.INCLUDE MULTI-FILE CASM
; COMMAND LINE USED. DDATA.S MUST STAY LAST SO ITS DATA BLOCK FOLLOWS ALL
; CODE. THIS IS NOW THE ONLY PLACE THAT ORDER IS SPECIFIED -- BOTH NATIVE
; CASM (CASM DMAIN.S /O:DASH.PRG) AND THE CA65 CROSS-CHECK (DASH_WRAPPER.S,
; WHICH JUST INCLUDES THIS FILE) READ IT FROM HERE.
.INCLUDE "DSCR.S"
.INCLUDE "DFMT.S"
.INCLUDE "DSYS.S"
.INCLUDE "DAPP.S"
.INCLUDE "DVMM.S"
.INCLUDE "DDATA.S"
